insert into public.templates (slug, name, document_type, description)
values ('aviso-legal', 'Aviso legal', 'aviso_legal', 'Plantilla de aviso legal')
on conflict (slug) do nothing;

insert into public.template_versions (template_id, version_label, is_demo, content, variables, rules, changelog, questionnaire_version)
select t.id, '0.1.0-demo', true, '{"title":"Aviso legal","intro":[{"type":"paragraph","text":"En cumplimiento del deber de información recogido en el artículo 10 de la Ley 34/2002, de 11 de julio, de Servicios de la Sociedad de la Información y de Comercio Electrónico (LSSI-CE), se facilitan a continuación los datos identificativos del titular del sitio web {{contact.website}}."}],"sections":[{"id":"datos-identificativos","heading":"Datos identificativos del titular","blocks":[{"type":"list","items":["Titular: {{owner.legal_name}}",{"text":"Nombre comercial: {{owner.trade_name}}","when":{"nonEmpty":"owner.trade_name"}},"NIF: {{owner.nif}}","Domicilio: {{owner.address_full}}","Correo electrónico: {{contact.email}}",{"text":"Teléfono: {{contact.phone}}","when":{"nonEmpty":"contact.phone"}},{"text":"Datos registrales: {{owner.registry_data}}","when":{"truthy":"owner.is_company"}}]}]},{"id":"profesion-regulada","heading":"Información sobre la profesión regulada","when":{"truthy":"professional.regulated"},"blocks":[{"type":"list","items":["Colegio profesional: {{professional.college}}","Número de colegiado: {{professional.number}}","Título académico y Estado de expedición: {{professional.title}}"]},{"type":"paragraph","text":"La actividad profesional se rige por las normas deontológicas y estatutarias aprobadas por {{professional.college}}, que pueden consultarse a través de los medios que dicho colegio pone a disposición del público."}]},{"id":"objeto","heading":"Objeto","blocks":[{"type":"paragraph","text":"Este aviso legal regula el acceso y el uso del sitio web {{contact.website}} (en adelante, el «sitio web»), mediante el cual {{owner.display_name}} ofrece información sobre su actividad: {{business.activity}}"},{"type":"paragraph","text":"El acceso al sitio web atribuye la condición de usuario e implica la aceptación de este aviso legal. Si no estás de acuerdo con su contenido, te rogamos que no utilices el sitio web."}]},{"id":"condiciones-uso","heading":"Condiciones de uso","blocks":[{"type":"paragraph","text":"El usuario se compromete a hacer un uso adecuado del sitio web y, en particular, a no:"},{"type":"list","items":["Utilizarlo con fines ilícitos o contrarios a la buena fe y al orden público.","Introducir o difundir virus informáticos o cualquier sistema que pueda causar daños.","Intentar acceder a áreas restringidas o a cuentas de otros usuarios.",{"text":"Publicar comentarios o reseñas con contenido ofensivo, falso o que vulnere derechos de terceros.","when":{"truthy":"data.comments"}}]}]},{"id":"propiedad-intelectual","heading":"Propiedad intelectual e industrial","blocks":[{"type":"paragraph","text":"Los contenidos del sitio web (textos, imágenes, diseño, logotipos y código) son titularidad de {{owner.display_name}} o de terceros que han autorizado su uso. Queda prohibida su reproducción, distribución o transformación sin autorización expresa, salvo para uso personal y privado."}]},{"id":"responsabilidad","heading":"Responsabilidad","blocks":[{"type":"paragraph","text":"{{owner.display_name}} procura que la información del sitio web sea correcta y esté actualizada, pero no garantiza la ausencia de errores ni la disponibilidad ininterrumpida del sitio web. No será responsable de los daños derivados de un uso indebido del sitio web por parte del usuario."}]},{"id":"enlaces","heading":"Enlaces a otros sitios web","blocks":[{"type":"paragraph","text":"El sitio web puede contener enlaces a páginas de terceros. {{owner.display_name}} no controla dichos sitios y no se responsabiliza de sus contenidos, sin perjuicio de retirar el enlace cuando tenga conocimiento efectivo de su ilicitud."}]},{"id":"contratacion","heading":"Contratación","when":{"truthy":"business.is_ecommerce"},"blocks":[{"type":"paragraph","text":"La compra de productos o servicios a través del sitio web se rige por las condiciones generales de contratación publicadas en el propio sitio web, que el usuario debe aceptar antes de completar cada pedido."}]},{"id":"proteccion-datos","heading":"Protección de datos y cookies","blocks":[{"type":"paragraph","text":"El tratamiento de los datos personales de los usuarios se describe en la política de privacidad, y el uso de cookies en la política de cookies, ambas disponibles en el sitio web."}]},{"id":"legislacion","heading":"Legislación aplicable y jurisdicción","blocks":[{"type":"paragraph","text":"Este aviso legal se rige por la legislación española. Para la resolución de cualquier controversia serán competentes los juzgados y tribunales que correspondan conforme a la normativa aplicable. Cuando el usuario tenga la condición de consumidor, serán competentes los de su domicilio."}]}],"closing":[{"type":"paragraph","text":"Última actualización: {{meta.generated_date}}."}]}'::jsonb, '[{"key":"business.activity"},{"key":"contact.email"},{"key":"contact.phone"},{"key":"contact.website"},{"key":"meta.generated_date"},{"key":"owner.address_full"},{"key":"owner.display_name"},{"key":"owner.legal_name"},{"key":"owner.nif"},{"key":"owner.registry_data"},{"key":"owner.trade_name"},{"key":"professional.college"},{"key":"professional.number"},{"key":"professional.title"}]'::jsonb,
       '[{"scope":"section:datos-identificativos/block:0/item:1","paths":["owner.trade_name"]},{"scope":"section:datos-identificativos/block:0/item:5","paths":["contact.phone"]},{"scope":"section:datos-identificativos/block:0/item:6","paths":["owner.is_company"]},{"scope":"section:profesion-regulada","paths":["professional.regulated"]},{"scope":"section:condiciones-uso/block:1/item:3","paths":["data.comments"]},{"scope":"section:contratacion","paths":["business.is_ecommerce"]}]'::jsonb, 'Borrador inicial de demostración pendiente de revisión jurídica.', 1
  from public.templates t
 where t.slug = 'aviso-legal'
   and not exists (select 1 from public.template_versions v where v.template_id = t.id and v.version_label = '0.1.0-demo');

insert into public.templates (slug, name, document_type, description)
values ('politica-privacidad', 'Política de privacidad', 'privacidad', 'Plantilla de política de privacidad')
on conflict (slug) do nothing;

insert into public.template_versions (template_id, version_label, is_demo, content, variables, rules, changelog, questionnaire_version)
select t.id, '0.1.0-demo', true, '{"title":"Política de privacidad","intro":[{"type":"paragraph","text":"En esta política te explicamos cómo trata {{owner.display_name}} los datos personales de las personas que visitan el sitio web {{contact.website}} o se ponen en contacto a través de él, conforme al Reglamento (UE) 2016/679 (RGPD) y a la Ley Orgánica 3/2018 (LOPDGDD)."}],"sections":[{"id":"responsable","heading":"Responsable del tratamiento","blocks":[{"type":"list","items":["Responsable: {{owner.legal_name}}","NIF: {{owner.nif}}","Domicilio: {{owner.address_full}}","Correo electrónico: {{contact.email}}",{"text":"Teléfono: {{contact.phone}}","when":{"nonEmpty":"contact.phone"}},{"text":"Delegado de Protección de Datos: {{data.dpo_contact}}","when":{"truthy":"data.has_dpo"}}]}]},{"id":"sin-recogida","heading":"Datos que tratamos","when":{"falsy":"data.collects_any"},"blocks":[{"type":"paragraph","text":"Este sitio web no recoge datos personales mediante formularios ni registros. Si nos escribes por correo electrónico, trataremos los datos que nos facilites únicamente para responder a tu mensaje, sobre la base de tu consentimiento, y los conservaremos mientras sea necesario para atenderlo."},{"type":"paragraph","text":"Durante la navegación, el proveedor de alojamiento puede tratar datos técnicos, como la dirección IP, para garantizar el funcionamiento y la seguridad del sitio web."}]},{"id":"finalidades","heading":"Finalidades, base jurídica y conservación","when":{"truthy":"data.collects_any"},"blocks":[{"type":"table","columns":["Finalidad","Base jurídica","Conservación"],"rows":[{"cells":["Atender las consultas que nos envías a través del formulario de contacto o por correo electrónico.","Tu consentimiento y, en su caso, la aplicación de medidas precontractuales a petición tuya (art. 6.1.a y 6.1.b RGPD).","El tiempo necesario para responder y, después, durante los plazos de prescripción de las posibles responsabilidades."],"when":{"truthy":"data.contact_form"}},{"cells":["Enviarte nuestra newsletter y comunicaciones sobre nuestra actividad.","Tu consentimiento (art. 6.1.a RGPD y art. 21 LSSI-CE).","Hasta que te des de baja o retires tu consentimiento."],"when":{"truthy":"data.newsletter"}},{"cells":["Gestionar tu cuenta de usuario y el acceso al área privada.","La ejecución de la relación contractual (art. 6.1.b RGPD).","Mientras mantengas tu cuenta activa y, después, durante los plazos legales aplicables."],"when":{"truthy":"data.accounts"}},{"cells":["Gestionar tus pedidos, pagos, envíos, devoluciones y la facturación.","La ejecución del contrato (art. 6.1.b RGPD) y el cumplimiento de obligaciones legales fiscales y mercantiles (art. 6.1.c RGPD).","Durante la relación contractual y los plazos exigidos por la normativa fiscal y mercantil."],"when":{"truthy":"data.orders"}},{"cells":["Gestionar tus reservas o citas.","La ejecución de la relación contractual o de medidas precontractuales (art. 6.1.b RGPD).","El tiempo necesario para prestar el servicio y, después, durante los plazos legales aplicables."],"when":{"truthy":"data.bookings"}},{"cells":["Valorar tu candidatura en procesos de selección.","Tu consentimiento y la aplicación de medidas precontractuales (art. 6.1.a y 6.1.b RGPD).","Hasta la finalización del proceso de selección o, si lo autorizas, durante un máximo de un año para futuros procesos."],"when":{"truthy":"data.job_applications"}},{"cells":["Publicar y moderar los comentarios o reseñas que envías.","Tu consentimiento (art. 6.1.a RGPD).","Mientras el comentario permanezca publicado o hasta que solicites su supresión."],"when":{"truthy":"data.comments"}}]}]},{"id":"categorias-especiales","heading":"Categorías especiales de datos","when":{"truthy":"data.special_categories"},"blocks":[{"type":"paragraph","text":"Para prestar nuestros servicios podemos tratar categorías especiales de datos, como datos de salud. Solo los trataremos cuando sea imprescindible y con tu consentimiento explícito u otra causa legitimadora prevista en el artículo 9.2 del RGPD, aplicando medidas de seguridad reforzadas."}]},{"id":"menores","heading":"Menores de edad","blocks":[{"type":"paragraph","text":"Cuando los datos correspondan a menores de 14 años, solo los trataremos con el consentimiento de sus padres, madres o tutores legales, que podremos solicitar que acrediten.","when":{"truthy":"data.minors"}},{"type":"paragraph","text":"Este sitio web no está dirigido a menores de 14 años. Si tienes menos de esa edad, no nos facilites tus datos sin el consentimiento de tus padres, madres o tutores legales.","when":{"falsy":"data.minors"}}]},{"id":"destinatarios","heading":"Destinatarios de los datos","blocks":[{"type":"paragraph","text":"No cederemos tus datos a terceros salvo obligación legal. Para prestar nuestros servicios contamos con proveedores que pueden acceder a los datos en calidad de encargados del tratamiento, con los que mantenemos los contratos exigidos por el artículo 28 del RGPD:"},{"type":"list","source":"processors","itemText":"{{item.name}}: {{item.purpose}}."}]},{"id":"transferencias","heading":"Transferencias internacionales","when":{"truthy":"international_transfers"},"blocks":[{"type":"paragraph","text":"Algunos de los proveedores indicados pueden tratar datos fuera del Espacio Económico Europeo. En esos casos, las transferencias se amparan en decisiones de adecuación de la Comisión Europea, como el Marco de Privacidad de Datos UE-EE. UU. para las entidades adheridas, o en cláusulas contractuales tipo aprobadas por la Comisión."}]},{"id":"derechos","heading":"Tus derechos","blocks":[{"type":"paragraph","text":"Puedes ejercer en cualquier momento los siguientes derechos escribiendo a {{contact.email}}, indicando el derecho que deseas ejercer:"},{"type":"list","items":["Acceso a tus datos personales.","Rectificación de los datos inexactos.","Supresión de tus datos.","Oposición al tratamiento y limitación del tratamiento.","Portabilidad de tus datos.","Retirada del consentimiento prestado, sin que ello afecte a la licitud del tratamiento previo."]},{"type":"paragraph","text":"Si consideras que no hemos atendido correctamente tus derechos, puedes presentar una reclamación ante la Agencia Española de Protección de Datos (www.aepd.es)."}]},{"id":"perfiles","heading":"Decisiones automatizadas","blocks":[{"type":"paragraph","text":"No tomamos decisiones basadas únicamente en el tratamiento automatizado de tus datos ni elaboramos perfiles.","when":{"falsy":"cookies.uses_advertising"}},{"type":"paragraph","text":"No tomamos decisiones basadas únicamente en el tratamiento automatizado de tus datos. Las cookies publicitarias de terceros que puedas aceptar pueden utilizarse para elaborar perfiles con fines publicitarios, tal como se explica en la política de cookies.","when":{"truthy":"cookies.uses_advertising"}}]},{"id":"seguridad","heading":"Seguridad","blocks":[{"type":"paragraph","text":"Aplicamos medidas técnicas y organizativas adecuadas para proteger tus datos frente a accesos no autorizados, pérdida o alteración."}]},{"id":"cambios","heading":"Cambios en esta política","blocks":[{"type":"paragraph","text":"Podemos actualizar esta política para adaptarla a cambios normativos o en nuestros tratamientos. Publicaremos siempre la versión vigente en el sitio web."}]}],"closing":[{"type":"paragraph","text":"Última actualización: {{meta.generated_date}}."}]}'::jsonb, '[{"key":"contact.email"},{"key":"contact.phone"},{"key":"contact.website"},{"key":"data.dpo_contact"},{"key":"meta.generated_date"},{"key":"owner.address_full"},{"key":"owner.display_name"},{"key":"owner.legal_name"},{"key":"owner.nif"}]'::jsonb,
       '[{"scope":"section:responsable/block:0/item:4","paths":["contact.phone"]},{"scope":"section:responsable/block:0/item:5","paths":["data.has_dpo"]},{"scope":"section:sin-recogida","paths":["data.collects_any"]},{"scope":"section:finalidades","paths":["data.collects_any"]},{"scope":"section:finalidades/block:0/row:0","paths":["data.contact_form"]},{"scope":"section:finalidades/block:0/row:1","paths":["data.newsletter"]},{"scope":"section:finalidades/block:0/row:2","paths":["data.accounts"]},{"scope":"section:finalidades/block:0/row:3","paths":["data.orders"]},{"scope":"section:finalidades/block:0/row:4","paths":["data.bookings"]},{"scope":"section:finalidades/block:0/row:5","paths":["data.job_applications"]},{"scope":"section:finalidades/block:0/row:6","paths":["data.comments"]},{"scope":"section:categorias-especiales","paths":["data.special_categories"]},{"scope":"section:menores/block:0","paths":["data.minors"]},{"scope":"section:menores/block:1","paths":["data.minors"]},{"scope":"section:transferencias","paths":["international_transfers"]},{"scope":"section:perfiles/block:0","paths":["cookies.uses_advertising"]},{"scope":"section:perfiles/block:1","paths":["cookies.uses_advertising"]}]'::jsonb, 'Borrador inicial de demostración pendiente de revisión jurídica.', 1
  from public.templates t
 where t.slug = 'politica-privacidad'
   and not exists (select 1 from public.template_versions v where v.template_id = t.id and v.version_label = '0.1.0-demo');

insert into public.templates (slug, name, document_type, description)
values ('politica-cookies', 'Política de cookies', 'cookies', 'Plantilla de política de cookies')
on conflict (slug) do nothing;

insert into public.template_versions (template_id, version_label, is_demo, content, variables, rules, changelog, questionnaire_version)
select t.id, '0.1.0-demo', true, '{"title":"Política de cookies","intro":[{"type":"paragraph","text":"En esta política te informamos sobre las cookies y tecnologías similares que se utilizan en el sitio web {{contact.website}}, titularidad de {{owner.legal_name}}, y sobre cómo puedes gestionarlas."}],"sections":[{"id":"que-son","heading":"¿Qué son las cookies?","blocks":[{"type":"paragraph","text":"Las cookies son pequeños archivos que se descargan en tu dispositivo al visitar una página web. Permiten, entre otras cosas, que la web funcione correctamente, recordar tus preferencias o conocer cómo se utiliza."}]},{"id":"cookies-utilizadas","heading":"Cookies que utiliza este sitio web","blocks":[{"type":"table","columns":["Cookie","Proveedor","Finalidad","Duración","Tipo"],"source":"cookies.list","cellTexts":["{{item.name}}","{{item.provider}}","{{item.purpose}}","{{item.duration}}","{{item.kind}}"],"empty":"Este sitio web no utiliza cookies propias ni de terceros que requieran información adicional, más allá de las estrictamente necesarias para su funcionamiento."},{"type":"paragraph","text":"Para obtener estadísticas de uso se utiliza Plausible, una herramienta de analítica que no instala cookies en tu dispositivo.","when":{"eq":["cookies.analytics_tool","plausible"]}},{"type":"paragraph","text":"El servicio de chat integrado puede instalar cookies propias del proveedor del servicio para mantener la conversación. Consulta la política del proveedor para más detalle.","when":{"truthy":"cookies.has_chat"}},{"type":"paragraph","text":"Esta relación se ha elaborado a partir de las herramientas utilizadas en el sitio web y puede variar si los proveedores modifican sus servicios. La revisamos periódicamente."}]},{"id":"consentimiento","heading":"Consentimiento","when":{"truthy":"cookies.has_nonessential"},"blocks":[{"type":"paragraph","text":"Las cookies técnicas son necesarias para el funcionamiento del sitio web y no requieren tu consentimiento. El resto de cookies (analíticas, de preferencias o publicitarias) solo se instalan si las aceptas."},{"type":"paragraph","text":"Al acceder por primera vez se muestra un panel, gestionado mediante {{cookies.cmp_name}}, en el que puedes aceptar, rechazar o configurar las cookies. Puedes cambiar tu elección o retirar tu consentimiento en cualquier momento desde ese mismo panel.","when":{"truthy":"cookies.has_cmp"}},{"type":"paragraph","text":"Antes de instalar estas cookies se te pedirá tu consentimiento, que podrás retirar en cualquier momento.","when":{"falsy":"cookies.has_cmp"}}]},{"id":"terceros","heading":"Cookies de terceros","when":{"truthy":"cookies.has_third_party"},"blocks":[{"type":"paragraph","text":"Algunas cookies son gestionadas por terceros. Estos proveedores tratan la información conforme a sus propias políticas de privacidad, que te recomendamos consultar."},{"type":"paragraph","text":"Las herramientas publicitarias utilizadas ({{cookies.advertising_labels}}) pueden utilizar la información obtenida para mostrarte publicidad basada en tus hábitos de navegación.","when":{"truthy":"cookies.uses_advertising"}},{"type":"paragraph","text":"Algunos de estos terceros pueden tratar los datos fuera del Espacio Económico Europeo con las garantías descritas en nuestra política de privacidad.","when":{"truthy":"international_transfers"}}]},{"id":"navegador","heading":"Cómo desactivar o eliminar las cookies desde el navegador","blocks":[{"type":"paragraph","text":"También puedes bloquear o eliminar las cookies desde la configuración de tu navegador:"},{"type":"list","items":["Google Chrome: https://support.google.com/chrome/answer/95647","Mozilla Firefox: https://support.mozilla.org/es/kb/habilitar-y-deshabilitar-cookies-sitios-web-rastrear-preferencias","Safari: https://support.apple.com/es-es/guide/safari/sfri11471/mac","Microsoft Edge: https://support.microsoft.com/es-es/microsoft-edge"]},{"type":"paragraph","text":"Si bloqueas todas las cookies, es posible que algunas funciones del sitio web no estén disponibles."}]},{"id":"actualizacion","heading":"Actualización de esta política","blocks":[{"type":"paragraph","text":"Actualizaremos esta política cuando cambien las cookies utilizadas. Para cualquier consulta puedes escribirnos a {{contact.email}}."}]}],"closing":[{"type":"paragraph","text":"Última actualización: {{meta.generated_date}}."}]}'::jsonb, '[{"key":"contact.email"},{"key":"contact.website"},{"key":"cookies.advertising_labels"},{"key":"cookies.cmp_name"},{"key":"meta.generated_date"},{"key":"owner.legal_name"}]'::jsonb,
       '[{"scope":"section:cookies-utilizadas/block:1","paths":["cookies.analytics_tool"]},{"scope":"section:cookies-utilizadas/block:2","paths":["cookies.has_chat"]},{"scope":"section:consentimiento","paths":["cookies.has_nonessential"]},{"scope":"section:consentimiento/block:1","paths":["cookies.has_cmp"]},{"scope":"section:consentimiento/block:2","paths":["cookies.has_cmp"]},{"scope":"section:terceros","paths":["cookies.has_third_party"]},{"scope":"section:terceros/block:1","paths":["cookies.uses_advertising"]},{"scope":"section:terceros/block:2","paths":["international_transfers"]}]'::jsonb, 'Borrador inicial de demostración pendiente de revisión jurídica.', 1
  from public.templates t
 where t.slug = 'politica-cookies'
   and not exists (select 1 from public.template_versions v where v.template_id = t.id and v.version_label = '0.1.0-demo');
